  "propositions": [
    {"id": "P1", "text": "A produção de Cannabis para fins medicinais deve ser liberada no Brasil."},
    {"id": "P2", "text": "A liberação do plantio de Cannabis medicinal reduzirá os custos dos medicamentos para pacientes vulneráveis."},
    {"id": "P3", "text": "A judicialização do acesso a medicamentos à base de Cannabis aumenta os gastos do Ministério da Saúde sem garantir acesso adequado aos pacientes mais necessitados."}
